{
  "mechanisms": [
    {
      "name": "asymmetric_learning_rates",
      "title": "Asymmetric Learning Rates",
      "description": "Separate learning rates are used for positive and negative prediction errors at both stages.",
      "params": [
        {
          "name": "alpha_pos",
          "bounds": [0, 1]
        },
        {
          "name": "alpha_neg",
          "bounds": [0, 1]
        }
      ],
      "evidence": "lr_stage1 = alpha_pos if delta_stage1 > 0 else alpha_neg\nq_stage1_mf[action_1[trial]] += lr_stage1 * delta_stage1\n...\nlr_stage2 = alpha_pos if delta_stage2 > 0 else alpha_neg\nq_stage2_mf[state_idx, action_2[trial]] += lr_stage2 * delta_stage2",
      "expressible_in_slots": true
    },
    {
      "name": "mb_mf_mixture",
      "title": "Model-Based / Model-Free Mixture",
      "description": "Stage 1 action values are a weighted mixture of model-based and model-free values.",
      "params": [
        {
          "name": "w",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_net = w * q_stage1_mb + (1 - w) * q_stage1_mf",
      "expressible_in_slots": true
    },
    {
      "name": "eligibility_trace",
      "title": "Eligibility Trace",
      "description": "Stage 1 model-free values are updated by the stage 2 prediction error scaled by an eligibility trace parameter.",
      "params": [
        {
          "name": "lam",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_mf[action_1[trial]] += lr_stage1 * lam * delta_stage2",
      "expressible_in_slots": true
    },
    {
      "name": "transition_dependent_stage1_stickiness",
      "title": "Transition-Dependent Stage 1 Stickiness",
      "description": "Stage 1 choice perseveration depends on whether the previous trial's transition was common or rare.",
      "params": [
        {
          "name": "pi1_comm",
          "bounds": [-5, 5]
        },
        {
          "name": "pi1_rare",
          "bounds": [-5, 5]
        }
      ],
      "evidence": "pi1 = pi1_comm if last_trans_common else pi1_rare\nexp_q1 = np.exp(beta * q_stage1_net + pi1 * stick_vector_1)",
      "expressible_in_slots": true
    },
    {
      "name": "stage2_stickiness",
      "title": "Stage 2 Choice Stickiness",
      "description": "A perseveration bonus is added to the stage 2 action chosen on the previous trial.",
      "params": [
        {
          "name": "pi2",
          "bounds": [-5, 5]
        }
      ],
      "evidence": "exp_q2 = np.exp(beta * q_stage2_mf[state_idx] + pi2 * stick_vector_2)",
      "expressible_in_slots": true
    }
  ]
}
